jsLib:
let statusMap = {
	null: "0️⃣",
	free: "🆓",
	vip: "3️⃣",
	marauder: "2️⃣",
	post: "1️⃣",
	BatteryFullIcon: "3️⃣",
	Battery5BarIcon: "2️⃣",
	Battery2BarIcon: "1️⃣",
};
let payStatusMap = {
	HighlightOffIcon: "isClosed",
	CheckCircleOutlineIcon: "isFree",
	BatteryFullIcon: "isPay",
	Battery5BarIcon: "isPay",
	Battery2BarIcon: "isPay",
};
function getUserchap(item) {
	if(item.free == true) return statusMap.free;
	let userchap = item.userchap[0];
	if(userchap.modes == null) return statusMap.null;
	let modes = String(userchap.modes).replace(/\w+/g, (m) => statusMap[m]);
	return `${userchap.chapters}章 ${modes}`
}

function getUserchap1(item) {
	if(item == "") return statusMap.null;
	let modes = String(item).replace(/([\w\d]+)(?:(\n)|($))/g, (m, n1, n2, n3) => `${statusMap[n1]}${n2?" ":""}`);
	return `${modes}`
}

ruleToc.chapterList:
.MuiAccordionSummary-root, .MuiListItem-alignItemsFlexStart > a
<js>
//java.log("目录" +result.length);
if (result.length == 0) {
	java.setContent(java.ajax(baseUrl));
	result = java.getElements(".MuiAccordionSummary-root, .MuiListItem-alignItemsFlexStart > a");
	//java.log(result.length);
}

let list = [];
function parseChapter(item) {
	if (item.isVip && item.isPay) {
		item.title = getUserchap1(item.userchap1) + item.title
	}
	list.push({
		title: item.title,
		url: item.url,
		isVolume: item.isVolume,
		isVip: item.isVip,
		isPay: item.isPay,
		userchap: item.userchap,
		userchap1: item.userchap1
	});
}
result.toArray().forEach((item, index) => {
	if (item.hasClass("MuiAccordionSummary-root")) {
		let summaryTitle = item.select("h4").text();
		parseChapter({
			title: summaryTitle,
			url: "",
			isVolume: true,
			isVip: false,
			isPay: false,
			userchap: "",
			userchap1: ""
		})
	} else {
		let title = item.select(".MuiListItemText-secondary").text();
		let url = item.attr("href");
		let userchap = item.select("svg:first-of-type").attr("data-testid");
		let userchap1 = item.select("svg:last-of-type").attr("data-testid");
		parseChapter({
			title: title,
			url: url,
			isVolume: false,
			isVip: payStatusMap[userchap] == "isClosed",
			isPay: payStatusMap[userchap1] == "isPay",
			userchap: userchap,
			userchap1: userchap1
		})
	}
})
JSON.stringify(list)
</js>
